// D3.js v7 minimal — vendored for Necropsy.
// In a full build, this would be the official D3 bundle.
// The UI uses minimal D3 interactions; core logic is in app.js.
if (typeof d3 === 'undefined') { window.d3 = {}; }
d3.select = function() { return { on: () => {}, style: () => {}, classed: () => {} }; };
d3.format = function(s) { return function(v) { return s.replace('~', v); }; };
d3.selectAll = function() { return { on: () => {}, style: () => {}, classed: () => {} }; };
d3.scaleLinear = function() { return { domain: () => {}, range: () => {} }; };
d3.scaleTime = function() { return d3.scaleLinear(); };
d3.axisBottom = function() { return { scale: () => {}, tickFormat: () => 'tick', tickSize: () => 0 }; };
d3.min = function(arr, f) { let v = Infinity; for (let i = 0; i < arr.length; i++) { const x = f(arr[i]); if (x < v) v = x; } return v; };
d3.max = function(arr, f) { let v = -Infinity; for (let i = 0; i < arr.length; i++) { const x = f(arr[i]); if (x > v) v = x; } return v; };